	private MagicMaxHit.MagicPrayer magicPrayer()
	{
		if (isActive(Prayer.AUGURY))
		{
			return MagicMaxHit.MagicPrayer.AUGURY;
		}
		if (isActive(Prayer.MYSTIC_VIGOUR))
